# Read a sheet (its id and today) as the store holds it now.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ readonly-transaction ]
# The sheet's people, in the order they were added.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: people
people:
  class: net.officefloor.hq.app.person.LoadPeople
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
# Load a sheet by id: a sheet never loaded before is created empty.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetRequest
  next: ensure
ensure:
  class: net.officefloor.hq.app.sheet.EnsureSheet
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ transaction ]
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository, Out<Sheet> sheet)
            throws SheetNotFoundException {
        Sheet found = repository.find(sheetId);
        if (found == null) {
            throw new SheetNotFoundException(sheetId);
        }
        sheet.set(found);
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithSheet {
    public void respond(@Val Sheet sheet, SheetRepository repository, ObjectResponse<SheetResponse> response) {
        response.send(SheetResponse.from(sheet, repository.parent(sheet.id())));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class EnsureSheet {
    public void ensure(@Val SheetRequest request, SheetRepository repository, Out<Sheet> sheet) {
        sheet.set(repository.ensure(request.id()));
    }
}
/** Proof kinds as the sheet's proof kinds take them: receipt or photo, comma separated. */
export const PROOF_KIND_LIST = /^\s*(receipt|photo)\s*(,\s*(receipt|photo)\s*)*$/;

/** Roles as a permission entry takes them: clerk or steward, comma separated. */
export const ROLE_LIST = /^\s*(clerk|steward)\s*(,\s*(clerk|steward)\s*)*$/i;

/** 0.00 or more, with at most two decimals. */
export const AMOUNT = /^(\d{1,13}(\.\d{1,2})?|\.\d{1,2})$/;

/** A percent: 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** A whole number, maybe negative. */
export const WHOLE = /^-?\d{1,9}$/;

/** 0 or more whole days. */
export const DAYS = /^\d{1,5}$/;

/** The query key for the sheet's settings; under sheetKey, so re-loading the sheet re-reads them. */
export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;

/** The sheet's settings. */
export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: !!sheet,
  });
}

/**
 * The grace days of the grade of a claim's person in force on its date, in force on that date (0: none): the claim is
 * overdue only once its due-by plus them is before the sheet's today.
 */
export function claimGrace(claim: { date: string }, grades: GradeFrom[], rules: DueRules): number {
  return rules.graceOn(gradeOn(grades, claim.date), claim.date);
}

/** The sheet's floor (two decimals): a claim's live due is at least it. */
export function useFloor(): string {
  return useSettings().data?.floor ?? DEFAULT_FLOOR;
}


/** The rounding modes a sheet can set. */
export const ROUNDING_MODES = ['half-up', 'half-even'] as const;

/** A date as the settings form takes it: yyyy-MM-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * What a claim's due is worked out from: the floor and late percent in force on a claim's date, the grace days of a grade
 * in force on a date (0: none), the sheet's today, its policy
 * date in force (blank: today), the rounding mode in force on a date ('': none, the policy date decides), its cap in force on today ('': none) and the dates of its claims by number (a correction rounds by the date
 * of the claim it corrects).
 */
export type DueRules = {
  floorOn: (date: string) => string;
  latePctOn: (date: string) => string;
  graceOn: (grade: string | undefined, date: string) => number;
  today: string;
  policyDate: string;
  roundingOn: (date: string) => string;
  cap: string;
  claimDates: Map<string, string>;
};

/** The sheet's rules for working out a claim's due. */
export function useDueRules(): DueRules {
  const settings = useSettings().data;
  const today = useSheetToday();
  const claims = useClaims().data;
  return useMemo(() => dueRules(settings, today, claims ?? []), [settings, today, claims]);
}

/** A sheet's rules for working out a claim's due, from its settings, its today and its claims. */
export function dueRules(settings: Settings | undefined, today: string, claims: Claim[]): DueRules {
  const history = settings?.history;
  return {
    floorOn: (date: string) => valueOn(history?.floor, date, DEFAULT_FLOOR),
    latePctOn: (date: string) => valueOn(history?.['late-pct'], date, DEFAULT_LATE_PCT),
    graceOn: (grade: string | undefined, date: string) => (grade ? Number(valueOn(history?.[`grace-${grade}`], date, '0')) : 0),
    today,
    policyDate: settings?.policyDate || today,
    roundingOn: (date: string) => valueOn(history?.rounding, date, ''),
    cap: settings?.cap ?? '',
    claimDates: new Map(claims.filter((c) => c.number !== null).map((c) => [c.number!, c.date])),
  };
}

